use std::{collections::HashMap,env,fs::File,io::{self,Read}};
#[derive(Default)] struct Row {calls:u64,input:u64,output:u64,read:u64,write:u64,cost:f64}
fn u(b:&[u8],i:usize)->u32{u32::from_le_bytes(b[i..i+4].try_into().unwrap())}fn d(b:&[u8],i:usize)->f64{f64::from_le_bytes(b[i..i+8].try_into().unwrap())}
fn add(map:&mut HashMap<u64,Row>,key:u64,b:&[u8]){let x=map.entry(key).or_default();x.calls+=1;x.input+=u(b,0) as u64;x.output+=u(b,4) as u64;x.read+=u(b,8) as u64;x.write+=u(b,12) as u64;x.cost+=d(b,16)}
fn main()->io::Result<()>{let mut args=env::args().skip(1);let mut f=File::open(args.next().unwrap())?;let cutoff:f64=args.next().unwrap().parse().unwrap();let mut maps:[HashMap<u64,Row>;5]=Default::default();let mut b=vec![0u8;56*32768];let mut count=0u64;
 loop{let mut n=0;while n<b.len(){let k=f.read(&mut b[n..])?;if k==0{break}n+=k}if n==0{break}if n%56!=0{return Err(io::Error::new(io::ErrorKind::InvalidData,"partial record"))}for r in b[..n].chunks_exact(56){let(s,a,m,t,day)=(u(r,24),u(r,28),u(r,32),u(r,36),u(r,40));if s>=256||a>=256{return Err(io::Error::new(io::ErrorKind::InvalidData,"ID exceeds numeric encoding"))}count+=1;add(&mut maps[0],s as u64,r);add(&mut maps[1],((s as u64)<<32)|a as u64,r);add(&mut maps[2],m as u64,r);add(&mut maps[3],t as u64,r);if d(r,48)>=cutoff{add(&mut maps[4],((day as u64)<<32)|s as u64,r)}}}
 print!("{{\"count\":{count},\"groups\":[");for(i,map)in maps.iter().enumerate(){if i>0{print!(",")}print!("[");let mut rows:Vec<_>=map.iter().map(|(key,value)|{let k=if i==1||i==4{format!("{}:{}",key>>32,key&0xffffffff)}else{key.to_string()};(k,value)}).collect();rows.sort_by(|a,b|a.0.cmp(&b.0));for(j,(k,v))in rows.iter().enumerate(){if j>0{print!(",")}print!("[\"{}\",{},{},{},{},{},{}]",k,v.calls,v.input,v.output,v.read,v.write,v.cost)}print!("]")}println!("]}}");Ok(())}
